def solve(nums):
    temp = [0] * len(nums)

    def merge(lo, mid, hi):
        i = lo
        j = mid
        k = lo

        while i < mid and j < hi:
            if nums[i] <= nums[j]:
                temp[k] = nums[i]
                i += 1
            else:
                temp[k] = nums[j]
                j += 1
            k += 1

        while i < mid:
            temp[k] = nums[i]
            i += 1
            k += 1

        while j < hi:
            temp[k] = nums[j]
            j += 1
            k += 1

        for idx in range(lo, hi):
            nums[idx] = temp[idx]

    def sort(lo, hi):
        if hi - lo <= 1:
            return

        mid = (lo + hi) // 2
        sort(lo, mid)
        sort(mid, hi)

        if nums[mid - 1] <= nums[mid]:
            return

        merge(lo, mid, hi)

    sort(0, len(nums))
    return nums
